#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<double> x(N), y(N);
    for(int i=0;i<N;i++) cin >> x[i] >> y[i];

    vector<bool> is_prime(N, false);
    {
        vector<bool> sieve(N, true);
        if(N>0) sieve[0]=false;
        if(N>1) sieve[1]=false;
        for(int i=2; (long long)i*i<N; i++)
            if(sieve[i])
                for(int j=i*i;j<N;j+=i) sieve[j]=false;
        is_prime=sieve;
    }

    auto rawDist=[&](int a,int b)->double{
        double dx=x[a]-x[b], dy=y[a]-y[b];
        return sqrt(dx*dx+dy*dy);
    };

    // step t (1-indexed): edge from tour[t-1] to tour[t]
    // penalty if t%10==0 and tour[t-1] is not prime
    auto edgeCost=[&](int from, int to, int step)->double{
        double d=rawDist(from,to);
        if(step%10==0 && !is_prime[from]) d*=1.1;
        return d;
    };

    // tour[0..N], tour[0]=tour[N]=0
    vector<int> tour(N+1);
    {
        // Nearest neighbor with spatial index
        tour[0]=0;
        vector<bool> visited(N,false);
        visited[0]=true;
        for(int i=1;i<N;i++){
            int last=tour[i-1];
            int best=-1; double bestd=1e18;
            for(int j=0;j<N;j++){
                if(!visited[j]){
                    double d=rawDist(last,j);
                    if(d<bestd){bestd=d;best=j;}
                }
            }
            tour[i]=best;
            visited[best]=true;
        }
        tour[N]=0;
    }

    auto tourCost=[&](const vector<int>&t)->double{
        double c=0;
        for(int s=1;s<=N;s++) c+=edgeCost(t[s-1],t[s],s);
        return c;
    };

    double bestCost=tourCost(tour);

    auto startTime=chrono::steady_clock::now();
    auto elapsed=[&]()->double{
        return chrono::duration<double>(chrono::steady_clock::now()-startTime).count();
    };

    // Or-opt (move single city) + 2-opt with full recalc but smarter
    // Since penalty depends on position, we must recalc affected edges
    // For or-opt: remove city at pos i, insert at pos j

    bool improved=true;
    while(improved && elapsed()<2.5){
        improved=false;
        // Or-opt: move city at position i to position j
        for(int i=1;i<N && elapsed()<2.5;i++){
            // Remove city tour[i]: reconnect tour[i-1]->tour[i+1]
            // Try inserting between j and j+1 for various j
            int city=tour[i];
            // Try a few candidate positions
            double oldCost=bestCost;
            int bestJ=-1; double bestNewCost=bestCost;

            // Remove and try reinsertion
            vector<int> tmp;
            tmp.reserve(N+1);
            for(int k=0;k<=N;k++) if(k!=i) tmp.push_back(tour[k]);
            // tmp has N elements (indices 0..N-1), tmp[0]=0, tmp[N-1]=0
            for(int j=0;j<(int)tmp.size()-1;j++){
                // insert city between tmp[j] and tmp[j+1]
                // This changes positions of everything after j
                // Too expensive to compute fully each time; just try and pick best by sampling
            }
            // Full recalc approach: just do 2-opt with full recalc
            // Skip or-opt, focus on 2-opt
            break;
        }

        // 2-opt with full recalc
        for(int i=1;i<N-1 && elapsed()<2.5;i++){
            for(int j=i+1;j<N && elapsed()<2.5;j++){
                if(j-i>200) break;
                reverse(tour.begin()+i,tour.begin()+j+1);
                double nc=tourCost(tour);
                if(nc<bestCost-1e-9){
                    bestCost=nc;
                    improved=true;
                } else {
                    reverse(tour.begin()+i,tour.begin()+j+1);
                }
            }
        }
    }

    cout<<N+1<<"\n";
    for(int i=0;i<=N;i++) cout<<tour[i]<<"\n";
}
